phones.append(phone('01a · Larger text', '<div style="text-align:right"><h2 style="font-size:72px;line-height:1.1">91</h2><p style="font-size:24px">days to Open</p></div><div class="mascot" style="position:relative;margin:0 auto" aria-label="Complete personalized companion"></div><hr class="agenda-divider" aria-label="Calendar progress toward competition; grey is days remaining">'+row('◇','Gentle stretching','8:30 PM · Move','✓')))
phones.append(phone('01b · Today on Sunday','<div class="hero"><h2>Countdown<small>days to your event</small></h2><div class="mascot" aria-label="Personalized companion"></div></div><section class="soft"><h3>◴ &nbsp; Weekly wrap-up <span class="right">›</span></h3><small>Jun 8–14</small></section>'+row('○','Weigh in','8:30 AM')+row('◇','Full-body strength','4:30 PM')))
pose_cells=''.join(f'<div><div class="action-mascot" style="background-position:{x}% {y}%" role="img" aria-label="{label}"></div><small>{label}</small></div>' for label,x,y in [('Food saved',0,0),('After BJJ',50,0),('Weights done',100,0),('Water done',0,100),('Event approaching',50,100),('Day completed',100,100)])
