phones.append(phone('02 · Week','<div class="detailhead"><span>‹</span><h3 style="color:#2465da" aria-label="Open wrap-up for Jun 8–14">◴ &nbsp; Jun 8–14</h3><span>›</span></div><div class="day"><strong>8 <span>Monday</span></strong><small>Recovery</small></div><div class="day"><strong>9 <span>Tuesday</span></strong><small>BJJ · 6:00 PM · ♡ 90 min recorded</small></div><div class="day"><strong>10 <span>Wednesday</span></strong></div>'+row('◇','Gentle stretching','8:30 PM · 10–15 min')+'<div class="day"><strong>11 <span>Thursday</span></strong><small>Weights · BJJ</small></div><div class="day"><strong>12 <span>Friday</span></strong><small>Recovery</small></div><div class="day"><strong>13 <span>Saturday</span></strong><small>BJJ · Moderate</small></div><div class="day"><strong>14 <span>Sunday</span></strong><small>Weight · Weights</small></div>'))
phones.append(phone('02a · Move workout',close('Move activity')+'<section class="soft"><h3>BJJ</h3><p>Today &nbsp; Tomorrow</p><p>Date · Jun 9</p><p>Time · 6:00 PM</p></section>'+actions('Move','Cancel activity'),False))
phones.append(phone('03 · Food','<div class="detailhead"><span>‹</span><h3>Wednesday, Jun 10</h3><span>›</span></div><div class="nutrition"><span class="action right">✎</span><h2>820 <small>/ 2,000 kcal</small></h2><div class="meter"><span style="width:41%"></span></div><div class="macros"><span><small>Protein</small><b>54 / 140 g</b></span><span><small>Carbs</small><b>90 / 220 g</b></span><span><small>Fat</small><b>27 / 60 g</b></span></div></div>'+row('◌','Eggs, toast and fruit','Breakfast · 380 kcal','')+row('◌','Chicken and rice','Lunch · 440 kcal','')+'<span class="right" aria-label="Restore dismissed meals">↶</span><p class="quiet">Breakfast dismissed <span class="right">Undo</span></p>'+row('◌','Dinner','7:00 PM · Fish, potatoes, vegetables','')+row('◌','Recovery snack','9:00 PM · Yogurt and berries','')))
phones.append(phone('04 · Food entry','<div class="detailhead"><span>×</span><span class="add">Add</span></div><div class="input">Two eggs, 80g toast and a banana</div><div class="quiet">Details ⌄</div>',False))
phones.append(phone('05 · Food review',close('')+'<section class="soft"><h3>Two eggs, 80g toast and a banana</h3><p>320g</p><h2>455 kcal</h2><p>21g protein · 65g carbs · 13g fat</p><span class="action right">✎</span></section><div class="save">✓</div>',False))
zones=''.join(f'<div class="zone"><small>Zone {i}</small><small>{t} min</small><div class="meter"><span style="width:{w}%"></span></div></div>' for i,t,w in [(1,18,20),(2,24,27),(3,22,25),(4,20,23),(5,2,3)])
phones.append(phone('06 · BJJ detail',close('BJJ')+'<small>Tuesday · 6:00 PM <span class="add">Move</span></small>'+actions()+'<section class="soft"><h2>90 min</h2><p>134 bpm avg · 176 peak</p>'+curve+'</section>'+zones+'<small>86 min covered · 4 min without HR</small><p class="add">Choose workout · Unlink workout</p>',False))
phones.append(phone('06a · Cold workout read',close('BJJ')+'<small>Tuesday · 6:00 PM</small>'+actions()+'<p class="quiet">Loading workout…</p><p class="add">Choose workout</p>',False))
phones.append(phone('07 · Strength',close('Weights')+'<small>Thursday · 4:00 PM · calendar-edit action</small>'+actions('Done','Skipped')+'<section class="mealpanel"><h3>20 min · Full body</h3><p>Open your selected strength app and choose a short full-body session.</p></section>',False))
phones.append(phone('07a · Strength feedback','<div class="detailhead"><span aria-label="Back">←</span><h3>Full-body weights</h3></div><small>Sunday · 11:00 AM</small><h2>How did it feel?</h2><section class="soft">Easy <span class="right">↗</span></section><section class="soft">About right <span class="right">＝</span></section><section class="soft">Too hard <span class="right">↘</span></section>',False))
phones.append(phone('07b · Next strength session',close('Weights')+'<small>Sunday · 11:00 AM</small>'+actions('Done','Skipped')+'<section class="soft">One more rep per set · Same weights</section>'+row('▣','Dumbbell row','3 × 11 · 20 lb','')+row('▣','Floor press','3 × 11 · 20 lb',''),False))
phones.append(phone('08 · Recovery',close('Gentle stretching')+'<small>Wednesday · 8:30 PM <span class="add">Move</span></small><section class="soft"><h3>10–15 min</h3><p>Open your chosen app and select gentle stretching. Keep it easy.</p>'+actions('Done')+'</section>',False))
phones.append(phone('09 · Weekly wrap-up',close('Weekly wrap-up')+'<small>Jun 8–14 <span class="right" aria-label="Refresh wrap-up">↻</span></small><section class="soft"><h2>Keep recovery close</h2><p>Your harder mat session and completed recovery make a useful pairing to keep in the schedule.</p></section>'+row('◇','Recovery alongside class','Tuesday’s recovery stayed attached to the late session. Keep that timing in view when moving class.','')+'<section class="mealpanel" style="padding:16px;border-radius:16px"><h3>→ &nbsp; Next week</h3><p><b style="color:#2465da">1</b> &nbsp; Keep recovery alongside the late class.</p><hr style="border:0;border-top:1px solid #d9e0e9"><p><b style="color:#2465da">2</b> &nbsp; Plan portions around each day’s accepted food target.</p></section><section class="mealpanel"><h3>Weight <span class="right" aria-label="Log weight">✎</span></h3>'+weight+'<small>Measurements · 7-day average</small></section>',False))
phones.append(phone('10 · Settings',close('Settings')+row('↻','Sync','Connected · Updated recently','›')+row('♡','Trackers','Sources, food sharing and refresh','›')+row('◷','Notifications','Permissions and quiet hours','›')+row('○','Weight goal','Your selected goal','›')+row('◌','Nutrition targets','Daily targets','›')+row('▤','Data','Export and restore','›'),False))
phones.append(phone('10b · Food sharing',close('Health Connect')+'<h3>Food logs</h3><p>Share saved calories and macros with Health Connect, including edits and deletions.</p><p class="quiet">Includes existing saved entries. Stopping sharing leaves already shared entries in Health Connect.</p><p class="add">Share food logs</p>',False))
