page=f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Personal Training App — Shareable Blueprint</title><style>{css}</style></head><body><main><header><div class="eyebrow">Shareable product blueprint · technology agnostic</div>{links}</header>{body}<footer>Self-contained document. No scripts, analytics, remote fonts, credentials or real personal records. Reference art embedded for illustration; choose a character for your own app.</footer></main></body></html>'
